INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT109-S3-Q18$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Industrial activities are purely beneficial to agriculture.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$More carbon dioxide intensifies photosynthesis, and industry raises carbon dioxide.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$One benefit is shown. The conclusion says the activity is purely beneficial, ignoring every possible harm.$batch12$), (3, $batch12$Goal$batch12$, $batch12$One benefit shown, so the thing is entirely good.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT109-S3-Q18$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
